sp_angular_provider.script:
function spReferenceElementV2() {

	return {
		restrict: "E",
        replace: true,
        scope: {
            ed: "=?",
            field: "=",
            refTable: "=?",
            refId: "=?",
            snOptions: "=?",
            snOnBlur: "&",
            snOnClose: "&",
            minimumInputLength: "@",
            snDisabled: "=",
            dropdownCssClass: "@",
            formatResultCssClass: "&",
            displayColumn: "@",
            recordValues: "&",
            getGlideForm: "&glideForm",
            domain: "@",
            snSelectWidth: "@",
            labelId: "@?",
			getColumns: "&",
			snChange: "&",
			onChange: "&",
			onCheckboxChange: "&"
        },
        template: '<div><div class="row"><div class="col-md-4" ng-repeat="column in ::getColumns(field)"><div class="form-check" ng-repeat="entry in column"><input class="form-check-input" type="checkbox" ng-model="field.checkboxes[entry.value].checked" ng-change="onCheckboxChange()"/><label class="form-check-label">{{entry.label}}</label></div></div></div>',
		link: function(scope, element) {
			var retColumns = null;
			var propName = 'sp_check_' + scope.field.name;
			scope.getColumns = function(field) {
				if (retColumns != null) {
					return retColumns;
				}
				retColumns = [];
				if (field.choices && field.choices.length > 0) {
					var startIndex = 0;
					var choicesLen = field.choices.length;
					if (field.choices[0].value == '') {
						startIndex = 1;
						choicesLen -= 1;
					}
					var numRows = Math.ceil(choicesLen / 3.0);
					for (var colIndex = 0; colIndex < 3; colIndex++) {
						var column = [];
						for (var rowIndex = 0; rowIndex < numRows; rowIndex++) {
							var choiceIndex = startIndex + colIndex * numRows;
							column.push(field.choices[choiceIndex + rowIndex]);
						}
						retColumns.push(column);
					}
				}
				console.log("GET CHOICES");
				console.log(retColumns);
				return retColumns;
			};

			scope.onChange = function() {
				console.log("ON CHANGE:");
				scope.field.value = scope.field.stagedValue;
				console.log(scope.field);
			};

			console.log(scope.field);
			console.log("Field show_checkboxes attribute: " + scope.field.attributes.show_checkboxes);
			var $el = element;
			var column_class = "col-md-2";
			while ($el) {
				if ($el.hasClass("col-md-12")) {
					column_class = "col-md-4";
					break;
				}
				else if ($el.hasClass("col-md-6")) {
					break;
				}
				$el = $el.parent();
			}
			console.log("Number of checkbox columns = " + column_class);

			// Convert initial value to array
			var initValues = scope.field.stagedValue.split(",");
			// Create fields for checkboxes
			scope.field.checkboxes = {};
			for ( var i = 0; i < scope.field.choices.length; i++) {
				if (scope.field.choices[i].value != '') {
					var entry = {
						checked: false,
						value: scope.field.choices[i].value
					};
					for (var j = 0; j < initValues.length; j++) {
						if (initValues[j] == entry.value) {
							entry.checked = true;
							break;
						}
					}
					scope.field.checkboxes[scope.field.choices[i].value] = entry;
				}
			}

			scope.onCheckboxChange = function() {
				var resultValue = '';
				for (var checkField in scope.field.checkboxes) {
					if (scope.field.checkboxes[checkField].checked) {
						if (resultValue != '') {
							resultValue += ',';
						}
						resultValue += scope.field.checkboxes[checkField].value;
					} 
					scope.field.stagedValue = resultValue;
					scope.field.value = resultValue;
					if (scope.snChange) {
						scope.snChange();
					}
				}
			};

		}
	}
}
